/* StudyFlow v2.1 - статична версія для GitHub Pages: замість Flask API - localStorage */
const DB_KEY='studyflow_v21';
const DB_SEED={tasks:[],settings:{sound:false,frequency:'after_task'}};
const dbLoad=()=>{try{const d=JSON.parse(localStorage.getItem(DB_KEY));if(d&&Array.isArray(d.tasks)&&d.settings)return d}catch(e){}return JSON.parse(JSON.stringify(DB_SEED))};
const dbSave=d=>{try{localStorage.setItem(DB_KEY,JSON.stringify(d))}catch(e){}};
const jsonRes=o=>Promise.resolve(new Response(JSON.stringify(o),{status:200,headers:{'Content-Type':'application/json'}}));
const uid=()=>(window.crypto&&crypto.randomUUID)?crypto.randomUUID():'id-'+Date.now()+'-'+Math.random().toString(36).slice(2);
const _fetch=window.fetch?window.fetch.bind(window):null;
window.fetch=async(u,o)=>{u=String(u);const m=(((o||{}).method)||'GET').toUpperCase();const cm=u.match(/\/tasks\/([^/]+)\/complete$/);if(cm&&m==='POST'){const d=dbLoad(),t=d.tasks.find(x=>x.id===decodeURIComponent(cm[1]));if(t){t.status='completed';t.completed_at=new Date().toISOString();dbSave(d)}return jsonRes({ok:!!t})}if(u.indexOf('/api/settings')>=0)return jsonRes(dbLoad().settings);if(u.indexOf('/api/tasks')>=0)return jsonRes(dbLoad().tasks);return _fetch?_fetch(u,o):jsonRes({})};
function flash(msg,cat){const box=document.querySelector('.flashes');if(!box)return;const p=document.createElement('p');p.className='flash '+(cat||'success');p.textContent=msg;box.appendChild(p);setTimeout(()=>p.remove(),2600)}
function taskHtml(t){return '<div class="task" data-id="'+t.id+'"><i></i><div class="taskinfo"><b>'+esc(t.title)+'</b><small>'+t.duration+' хв</small></div><details><summary>•••</summary><div class="menu"><form action="/tasks/'+t.id+'/edit" method="post"><input name="title" value="'+esc(t.title)+'" required><input name="duration" type="number" min="1" max="600" value="'+t.duration+'" required><button class="mini">Зберегти</button></form><form action="/tasks/'+t.id+'/delete" method="post"><button class="mini red">Видалити</button></form></div></details></div>'}
function renderList(){const d=dbLoad();const pend=d.tasks.filter(x=>x.status==='pending'),comp=d.tasks.filter(x=>x.status==='completed');const list=document.querySelector('.task-list');if(list)list.innerHTML=pend.length?pend.map(taskHtml).join(''):'<p class="muted center">Поки немає завдань. Додай перше ☝️</p>';const c=document.querySelector('.count');if(c)c.textContent=pend.length;const old=document.querySelector('.completed');if(old)old.outerHTML='<details class="completed"><summary>✓ Виконані завдання ('+comp.length+')</summary>'+(comp.length?comp.map(t=>'<div class="restore">✓ '+esc(t.title)+' · '+t.duration+' хв<form action="/tasks/'+t.id+'/restore" method="post"><button class="mini">Повернути</button></form></div>').join(''):'<p class="muted">Тут з\'являться виконані завдання.</p>')+'</details>';checkTimeWarn()}
function syncSettings(){const d=dbLoad();const sb=document.querySelector('[name=sound]');if(sb)sb.checked=!!d.settings.sound;const fr=document.querySelector('[name=frequency][value="'+(d.settings.frequency||'after_task')+'"]');if(fr)fr.checked=true}
document.addEventListener('submit',e=>{const f=e.target,act=f.getAttribute('action')||'';let m;if(act==='/tasks/add'){e.preventDefault();const d=dbLoad(),title=(f.elements.title.value||'').trim(),dur=parseInt(f.elements.duration.value,10);if(!title||!(dur>=1&&dur<=600)){flash('Введіть назву та тривалість від 1 до 600 хв.','error');return}d.tasks.push({id:uid(),title,duration:dur,status:'pending',created_at:new Date().toISOString()});dbSave(d);flash('Завдання додано.','success');f.reset();f.elements.duration.value=25;renderList();return}
m=act.match(/^\/tasks\/([^/]+)\/edit$/);if(m){e.preventDefault();const d=dbLoad(),t=d.tasks.find(x=>x.id===decodeURIComponent(m[1]));if(!t)return;const title=(f.elements.title.value||'').trim(),dur=parseInt(f.elements.duration.value,10);if(title&&dur>=1&&dur<=600){t.title=title;t.duration=dur;dbSave(d);flash('Завдання оновлено.','success')}else flash('Перевірте назву та тривалість.','error');renderList();return}
m=act.match(/^\/tasks\/([^/]+)\/delete$/);if(m){e.preventDefault();const d=dbLoad();d.tasks=d.tasks.filter(x=>x.id!==decodeURIComponent(m[1]));dbSave(d);renderList();return}
m=act.match(/^\/tasks\/([^/]+)\/restore$/);if(m){e.preventDefault();const d=dbLoad(),t=d.tasks.find(x=>x.id===decodeURIComponent(m[1]));if(t){t.status='pending';delete t.completed_at;dbSave(d)}renderList();return}
if(act==='/settings'){e.preventDefault();const d=dbLoad();d.settings={sound:f.elements.sound.checked,frequency:(f.elements.frequency&&f.elements.frequency.value)||'after_task'};dbSave(d);flash('Налаштування збережено.','success');syncSettings();return}});
const $=id=>document.getElementById(id);let s=null,interval=null,rem5=false;
const fmt=n=>{n=Math.max(0,Math.floor(n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};
function ping(){try{let A=new(window.AudioContext||window.webkitAudioContext)(),o=A.createOscillator(),g=A.createGain();o.frequency.value=850;g.gain.value=.06;o.connect(g);g.connect(A.destination);o.start();o.stop(A.currentTime+.15)}catch(e){}}
function note(title,msg){alert(title+'\n'+msg);if(document.querySelector('[name=sound]')?.checked)ping();if('Notification'in window&&Notification.permission==='granted')new Notification(title,{body:msg})}
function render(){if(!s)return;$('sessionTimer').textContent=fmt(s.left);$('status').textContent=s.state==='run'?'Навчання':'Пауза';$('active').classList.remove('hidden');$('empty').classList.add('hidden');$('start').classList.add('hidden');$('minutes').disabled=true;let t=s.items[s.i];if(t){$('taskTitle').textContent=t.title;$('position').textContent=(s.i+1)+' / '+s.items.length;$('taskTimer').textContent=fmt(t.left);$('progress').style.width=Math.min(100,100*(1-t.left/t.plan))+'%'}$('pause').textContent=s.state==='run'?'Ⅱ Пауза':'▶ Продовжити';$('sessionTasks').innerHTML=s.items.map((x,i)=>'<div>'+(x.done?'✓':i===s.i?'▶':'○')+' '+esc(x.title)+' · '+Math.round(x.plan/60)+' хв</div>').join('');document.body.classList.toggle('running',!!s&&s.state==='run')}
function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function start(){let mins=Number($('minutes').value);if(!Number.isInteger(mins)||mins<1||mins>600)return alert('Тривалість: 1–600 хв.');let cfg={};try{cfg=await(await fetch('/api/settings')).json()}catch(e){}let tasks=await(await fetch('/api/tasks')).json(),items=[],sum=0;for(let t of tasks.filter(x=>x.status==='pending')){let n=t.duration*60;if(sum+n>mins*60)continue;items.push({id:t.id,title:t.title,plan:n,left:n,done:false});sum+=n}if(!items.length)return alert('Немає завдань, які вміщуються у час сесії.');s={plan:mins*60,left:mins*60,items,i:0,state:'run',last:Date.now()/1000,frequency:cfg.frequency||'after_task'};rem5=false;$('result').classList.add('hidden');render();interval=setInterval(tick,250)}
function tick(){if(!s||s.state!=='run')return;let now=Date.now()/1000,dt=now-s.last;s.last=now;s.left=Math.max(0,s.left-dt);let t=s.items[s.i];if(t)t.left=Math.max(0,t.left-dt);if(!rem5&&s.left<=300&&s.left>0){rem5=true;note('Залишилося 5 хвилин','Сесія скоро завершиться.')}render();if(t&&t.left<=0&&!t.done){s.state='pause';render();taskPrompt()}if(s.left<=0)finish()}
function taskPrompt(){if($('taskPrompt'))return;let d=document.createElement('div');d.id='taskPrompt';d.className='notice';d.innerHTML='<b>Час завдання завершився. Виконано?</b><div class="buttons"><button class="success" id="yes">Так, виконано</button><button class="light" id="more">Продовжити (+5 хв)</button><button class="light" id="skip">Наступне завдання</button></div>';$('active').append(d);$('yes').onclick=done;$('more').onclick=()=>{s.items[s.i].left=300;s.last=Date.now()/1000;s.state='run';d.remove();render()};$('skip').onclick=async()=>{s.items.splice(s.i,1);d.remove();await refill();advance();render()}}
function advance(){let rest=s.items.slice(s.i).filter(x=>!x.done);if(rest.length){let nx=rest[0];s.i=s.items.indexOf(nx);nx.left=nx.plan;s.state='run';s.last=Date.now()/1000}else{s.state='pause';$('allDone').classList.remove('hidden')}}
async function refill(){if(!s||s.left<60)return;let tasks=await(await fetch('/api/tasks')).json(),inS=new Set(s.items.map(x=>x.id));for(let t of tasks.filter(x=>x.status==='pending'&&!inS.has(x.id))){let n=t.duration*60;if(n<=s.left){s.items.push({id:t.id,title:t.title,plan:n,left:n,done:false});inS.add(t.id)}}}
function refreshSidebar(t){let el=document.querySelector('.task[data-id="'+t.id+'"]');if(el)el.remove();let c=document.querySelector('.count');if(c)c.textContent=document.querySelectorAll('.task').length;let det=document.querySelector('.completed');if(det){let d=document.createElement('div');d.className='restore';d.innerHTML='✓ '+esc(t.title)+' · '+Math.round(t.plan/60)+' хв<form action="/tasks/'+t.id+'/restore" method="post"><button class="mini">Повернути</button></form>';det.append(d);let sum=det.querySelector('summary');if(sum)sum.textContent='✓ Виконані завдання ('+det.querySelectorAll('.restore').length+')'}checkTimeWarn()}
function checkTimeWarn(){let w=$('timeWarn');if(!w)return;if($('minutes').disabled){w.classList.add('hidden');return}let mins=Number($('minutes').value)||0,sum=0;document.querySelectorAll('.task small').forEach(x=>{let n=parseInt(x.textContent);if(!isNaN(n))sum+=n});let over=sum>mins;w.classList.toggle('hidden',!over);if(over)w.textContent='⚠️ Сумарний час завдань ('+sum+' хв) більший за тривалість сесії ('+mins+' хв) — частина завдань не вміститься.'}
async function done(){let t=s.items[s.i];t.done=true;await fetch('/tasks/'+t.id+'/complete',{method:'POST'});$('taskPrompt')?.remove();if((s.frequency||'after_task')!=='end_session')note('Завдання виконано',t.title);refreshSidebar(t);await refill();advance();render()}
function finish(){if(!s)return;clearInterval(interval);s.state='end';document.body.classList.remove('running');let done=s.items.filter(x=>x.done),left=s.items.filter(x=>!x.done);$('used').textContent=fmt(s.plan-s.left);$('doneCount').textContent=done.length;$('leftCount').textContent=left.length;$('resultLists').innerHTML='<p><b>Виконано:</b><br>'+done.map(x=>'✓ '+esc(x.title)).join('<br>')+'</p><p><b>Не виконано:</b><br>'+left.map(x=>'○ '+esc(x.title)).join('<br>')+'</p>';$('result').classList.remove('hidden');$('active').classList.add('hidden');$('allDone').classList.add('hidden');$('start').classList.remove('hidden');$('minutes').disabled=false;$('empty').classList.remove('hidden');$('empty').textContent='Сесію завершено. Можеш запустити нову.';$('status').textContent='Завершено';let doneTitles=done.map(x=>x.title).join(', ');note('Сесію завершено',((s.frequency||'after_task')==='end_session'&&done.length)?'Виконано: '+done.length+' - '+doneTitles:'Переглянь результат.');checkTimeWarn()}
const themeRoot=document.documentElement,MODES=['light','dark','video'],STYLES=['blue','red','green','lucky'],LUCKY_PROPS=['--blue','--dot','--ring','--count-bg','--clock-border','--bar-bg'];
let curMode='light',curStyle='blue';
function hsl(h,s,l){return 'hsl('+h+' '+s+'% '+l+'%)'}
function luckyPalette(h){const dark=curMode==='dark',sat=dark?55:75,accents=[[h,sat,dark?64:48],[(h+45)%360,sat,dark?60:46],[(h+100)%360,sat,dark?57:44]];[themeRoot].concat([].slice.call(document.querySelectorAll('.card'))).forEach((el,i)=>{const a=accents[i%3];LUCKY_PROPS.forEach(k=>{let v=null;if(k==='--blue'||k==='--dot')v=hsl(a[0],a[1],a[2]);else if(k==='--ring')v=hsl(a[0],dark?55:70,dark?42:76);else if(k==='--count-bg')v=hsl(a[0],dark?40:75,dark?26:91);else if(k==='--clock-border')v=hsl(a[0],dark?35:60,dark?30:86);else if(k==='--bar-bg')v=hsl(a[0],dark?35:55,dark?30:89);if(v)el.style.setProperty(k,v)})})}
function clearLucky(){[themeRoot].concat([].slice.call(document.querySelectorAll('.card'))).forEach(el=>LUCKY_PROPS.forEach(k=>el.style.removeProperty(k)))}
function applyTheme(m,st){if(!MODES.includes(m))m='light';if(!STYLES.includes(st))st='blue';curMode=m;curStyle=st;themeRoot.dataset.mode=m;themeRoot.dataset.style=st;const bv=$('bgVideo');if(bv){const f=bv.querySelector('iframe');if(m==='video'){if(!f.src)f.src=f.dataset.src;bv.classList.remove('hidden')}else{bv.classList.add('hidden');if(f.src)f.removeAttribute('src')}}if(st==='lucky'){let hs=null;try{hs=localStorage.getItem('luckyHue')}catch(e){}if(hs===null){hs=Math.floor(Math.random()*360);try{localStorage.setItem('luckyHue',hs)}catch(e){}}luckyPalette(+hs)}else clearLucky();try{localStorage.setItem('mode',m);localStorage.setItem('style',st)}catch(e){}document.querySelectorAll('#themePanel [data-mode]').forEach(b=>b.classList.toggle('on',b.dataset.mode===m));document.querySelectorAll('#themePanel [data-style]').forEach(b=>b.classList.toggle('on',b.dataset.style===st))}
let sm=null,ssv=null;try{sm=localStorage.getItem('mode');ssv=localStorage.getItem('style')}catch(e){}
applyTheme(sm||'light',ssv||'blue');
$('themeBtn').onclick=e=>{e.stopPropagation();$('themePanel').classList.toggle('hidden')};
document.addEventListener('click',e=>{if(!e.target.closest('.theme-picker'))$('themePanel').classList.add('hidden')});
$('themePanel').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.mode)applyTheme(b.dataset.mode,curStyle);else if(b.dataset.style==='lucky'){const h=Math.floor(Math.random()*360);try{localStorage.setItem('luckyHue',h)}catch(e){}applyTheme(curMode,'lucky')}else if(b.dataset.style)applyTheme(curMode,b.dataset.style);$('themePanel').classList.add('hidden')});
$('start').onclick=start;$('done').onclick=done;$('pause').onclick=()=>{if(!s)return;if(s.state==='run'){s.state='pause';clearInterval(interval)}else{s.state='run';s.last=Date.now()/1000;interval=setInterval(tick,250)}render()};$('stop').onclick=finish;$('finishAll').onclick=finish;$('new').onclick=()=>{s=null;$('result').classList.add('hidden');$('active').classList.add('hidden');$('allDone').classList.add('hidden');$('empty').classList.remove('hidden');$('start').classList.remove('hidden');$('minutes').disabled=false;$('status').textContent='Не запущено';$('sessionTimer').textContent=fmt(Number($('minutes').value)*60);checkTimeWarn()};
$('minutes').addEventListener('input',checkTimeWarn);checkTimeWarn();

renderList();syncSettings();
